function Hd = FTDesignAstop20
%FTDESIGNASTOP20 返回离散时间滤波器对象�??

% MATLAB Code
% Generated by MATLAB(R) 9.10 and DSP System Toolbox 9.12.
% Generated on: 10-Mar-2022 16:53:40

% Equiripple Lowpass filter designed using the FIRPM function.

% All frequency values are in Hz.
Fs = 15625;  % Sampling Frequency

Fpass = 2400;            % Passband Frequency
Fstop = 3550;            % Stopband Frequency
Dpass = 0.015;  % Passband Ripple
Dstop = 0.01;             % Stopband Attenuation
dens  = 20;              % Density Factor

% Calculate the order from the parameters using FIRPMORD.
[N, Fo, Ao, W] = firpmord([Fpass, Fstop]/(Fs/2), [1 0], [Dpass, Dstop]);

% Calculate the coefficients using the FIRPM function.
b  = firpm(N, Fo, Ao, W, {dens});
Hd = dfilt.dffir(b);

